plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // This dependency is used by the application.
    implementation(libs.guava)
    // Source: https://mvnrepository.com/artifact/io.milvus/milvus-sdk-java
    implementation("io.milvus:milvus-sdk-java:3.0.10")
    // Source: https://mvnrepository.com/artifact/org.slf4j/slf4j-log4j12
    implementation("org.slf4j:slf4j-log4j12:2.0.20")
    implementation("dev.langchain4j:langchain4j:1.22.0")
    implementation("dev.langchain4j:langchain4j-embeddings-bge-small-en-v15-q:1.22.0-beta32")
    implementation("dev.langchain4j:langchain4j-easy-rag:1.22.0-beta32")
    implementation("org.testcontainers:testcontainers-milvus:2.0.5")
    implementation("dev.langchain4j:langchain4j-milvus-v2:1.22.0-beta32")
    implementation("org.duckdb:duckdb_jdbc:1.1.3")
    implementation("org.hdrhistogram:HdrHistogram:2.2.2")

}

testing {
    suites {
        // Configure the built-in test suite
        val test = named<JvmTestSuite>("test") {
            // Use JUnit Jupiter test framework
            useJUnitJupiter("6.0.1")
        }
    }
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

application {
    // Define the main class for the application.
    mainClass = "org.example.App"
}

// щоб System.in працював під `./gradlew run` (пауза перед зупинкою контейнера)
tasks.named<JavaExec>("run") {
    standardInput = System.`in`
}
